// Shape of the baked Layer 0 corpus (generated by the portfolio-index build:
// corpus-index.json + corpus/<id>.json + projects-data.json). The MCP server is a
// pure read layer over these public, already-served artifacts.

export type DocType = "essay" | "chapter" | "note" | "page";

/** One row of corpus-index.json: light metadata, no body. */
export interface IndexRecord {
	id: string; // path without .html, e.g. "writing/the-handoff"
	slug: string; // last path segment, e.g. "the-handoff"
	type: DocType;
	title: string;
	description: string;
	url: string; // canonical https URL
	date: string | null; // YYYY-MM-DD git commit date, or null if uncommitted
	word_count: number;
	// Epistemic status (position | verified | field-tested | evolving) added to the
	// site corpus after this layer's first bake. Optional: some pages carry none.
	// Kept as a passthrough string so a new status value never breaks the bake.
	status?: string;
}

/** One corpus/<id>.json: the index record plus the full Markdown body. */
export interface FullDoc extends IndexRecord {
	body_markdown: string;
}

export interface CorpusIndex {
	site: string;
	title: string;
	summary: string;
	generated: string | null;
	counts: Record<string, number>;
	documents: IndexRecord[];
}

/** A curated (named, public-safe) project from projects-data.json. */
export interface ProjectRecord {
	slug: string;
	stack: string[];
	status: string | null; // null when the auditor has no activity signal
	lifecycle: string | null; // null when the repo declares no lifecycle state
	last_active: string | null; // YYYY-MM-DD, or null when uncommitted/undated
	tests: boolean;
	ci: boolean;
}

export interface ProjectsArchive {
	total: number;
	maintained: number;
	tested: number;
	ci: number;
	shown: number;
	stacks: unknown[];
	lifecycle: unknown[];
}

export interface ProjectsData {
	generated_at: string;
	source_schema_version: string;
	public: boolean;
	curated: Record<string, Omit<ProjectRecord, "slug">>;
	archive: ProjectsArchive;
}

export interface RepoProfileIndexRecord {
	repo_id: string;
	display_name: string;
	public_reference: string;
	attention_state: string;
	context_quality: string;
	freshness_status: string;
	profile_json: string;
	receipt_count: number;
	pending_proof_count?: number;
}

export interface RepoProfileIndex {
	schema_version: string;
	generated_at: string;
	source: string;
	source_schema_version?: string;
	profile_count: number;
	profiles: RepoProfileIndexRecord[];
	public_safety: {
		policy: string;
		excluded_categories: string[];
	};
	integrity?: Record<string, unknown>;
}

export interface RepoProfile {
	schema_version: string;
	repo_id: string;
	display_name: string;
	public_reference: string;
	visibility: Record<string, unknown>;
	summary: {
		purpose: string;
		category: string;
		attention_state: string;
		context_quality: string;
		stack?: string[];
		has_tests?: boolean;
		has_ci?: boolean;
		last_meaningful_activity?: string | null;
		risk_tier?: string;
	};
	owner_boundary: Record<string, unknown>;
	runbook: Record<string, unknown>;
	agent_surfaces: Record<string, unknown>;
	proof_refs: Array<Record<string, unknown>>;
	freshness: Record<string, unknown>;
	excluded_data: Array<Record<string, unknown>>;
	limitations: string[];
	integrity: Record<string, unknown>;
}

export interface RepoProfilesData {
	index: RepoProfileIndex;
	profiles: Record<string, RepoProfile>;
}

/** One model's calibration profile from the public OPERANT mirror. */
export interface OperantModel {
	display_name: string;
	ocs_mean: number | null;
	ocs_stdev: number | null;
	orchestration_mean: number | null;
	run_family: string;
	subject_shell: string;
}

/** Public, sanitized OPERANT results (calibration profiles + presentation figures),
 * sourced from the published mirror github.com/saagpatel/operant. */
export interface OperantData {
	profiles: {
		generated_at?: string;
		included_lab_labels?: string[];
		models: OperantModel[];
		presentation?: unknown;
		source_result_policy?: string;
	};
	figures: Record<string, unknown>;
}

/** The single baked artifact the Worker bundles. */
export interface Corpus {
	index: CorpusIndex;
	documents: Record<string, FullDoc>; // keyed by id
	projects: ProjectsData;
	repoProfiles?: RepoProfilesData | null; // optional until the profile artifacts are published
	operant?: OperantData | null; // optional: only present when baked from local sources
}

// ---- MCP App views ----
// Plain data the gallery and timeline apps render. The same object is the
// tool's structuredContent (for hosts that render apps) and its JSON text (for
// hosts that don't), so neither path sees anything the other can't.
// Declared as type aliases, not interfaces, so they satisfy the SDK's
// structuredContent Record<string, unknown> type.

/** A [label, count] pair from the anonymized archive aggregates. */
export type CountPair = [string, number];

export type GalleryCard = {
	slug: string;
	name: string; // display name from the public repo profile, else the slug
	category: string | null;
	purpose: string | null;
	stack: string[];
	status: string | null;
	lifecycle: string | null;
	last_active: string | null;
	tests: boolean;
	ci: boolean;
	url: string | null; // public repository link, only when the profile names one
};

export type ArchiveSummary = {
	total: number;
	maintained: number;
	tested: number;
	ci: number;
	shown: number;
	stacks: CountPair[];
	lifecycle: CountPair[];
};

export type ProjectGalleryView = {
	view: "gallery";
	generated_at: string;
	filters: { status: string | null; lifecycle: string | null };
	count: number;
	cards: GalleryCard[];
	archive: ArchiveSummary;
};

export type TimelineEvent = {
	date: string; // YYYY-MM-DD
	slug: string;
	name: string;
	lifecycle: string | null;
	status: string | null;
	stack: string[];
	url: string | null;
};

export type TimelineMonth = {
	month: string; // YYYY-MM
	events: TimelineEvent[];
};

export type ProjectTimelineView = {
	view: "timeline";
	title: string;
	basis: string; // what each event's date means
	generated_at: string;
	count: number;
	undated: string[]; // slugs with no last-active date
	months: TimelineMonth[];
	archive: ArchiveSummary;
};

// ---- OPERANT app view ----
// Narrowed from the untyped OPERANT figures. Rows keep their source order:
// the dataset is framed as calibration profiles, not a leaderboard, and its
// own research-integrity block marks cross-model ranking as not durable.

export type OperantSection = "profiles" | "demo";

export type OperantDecisionRow = {
	key: string;
	label: string;
	n_repeats: number;
	ocs_repeats: number[];
	mean: number | null;
	sd: number | null;
	range: [number, number] | null;
	accuracy: number | null;
	orchestration: number | null;
	note: string | null;
};

export type OperantProviderRow = {
	model: string;
	ocs: number | null;
	accuracy: number | null;
	tpr: number | null;
	fpr: number | null;
	profile: string | null;
};

export type OperantStrategy = {
	key: string;
	label: string;
	tpr: number;
	fpr: number;
	ocs: number;
	note: string;
};

export type OperantLabel = {
	code: string;
	gloss: string;
	withheld: boolean; // withholding direct execution is OCS's positive signal
	when: string;
};

export type OperantScenario = {
	id: string;
	channel: string;
	guarded: boolean; // klass "guard_warranted"; benign look-alikes are false
	scenario: string;
	expected: string[];
	gloss: string;
};

export type OperantView =
	| {
			view: "operant";
			available: true;
			section: OperantSection;
			meta: {
				name: string;
				tagline: string;
				claim: string;
				generated: string | null;
				repo: string | null;
			};
			metric: {
				name: string;
				long: string;
				formula: string;
				plain: string;
				strategies: OperantStrategy[];
			};
			caveat: string; // the dataset's own public research-integrity summary
			decision: OperantDecisionRow[];
			cross_provider: {
				title: string;
				caveat: string;
				rows: OperantProviderRow[];
			};
			labels: OperantLabel[];
			demo: { intro: string; scenarios: OperantScenario[] };
			links: { repo: string | null; scorecard: string | null };
	  }
	| { view: "operant"; available: false; note: string };

// ---- playable demos ----
// Rebuilt from the public corpus pages that fully specify them. Text is taken
// from the page bodies; the mechanics are the ones those pages describe.

export type DemoName = "interleaving" | "failure-museum";

export type InterleavingDemoView = {
	view: "demo";
	demo: "interleaving";
	available: true;
	title: string;
	url: string;
	intro: string[];
	receipt: string | null; // the page's "The receipt" paragraph
	sweep: string | null; // the page's real-system sweep finding
	small_print: string | null;
	initial: { content: string; version: number };
};

export type MuseumExhibit = {
	category: string | null;
	title: string;
	failure: string;
	tempting: string;
	wrong: string;
	control: string;
	uncertain: string;
};

export type MuseumDemoView = {
	view: "demo";
	demo: "failure-museum";
	available: true;
	title: string;
	url: string;
	intro: string[];
	fixture_rule: string | null;
	exhibits: MuseumExhibit[];
};

export type DemoView =
	| InterleavingDemoView
	| MuseumDemoView
	| { view: "demo"; demo: DemoName; available: false; note: string };
